/**
 ******************************************************************************
 * @file    crossover.h
 * TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tom's sound output subsystem (best-ui), with an AI coding assistant.
 * @brief   Speaker crossover: highs to the tweeter (left), lows to the
 *          subwoofer (right), split at one point, 1600 Hz.
 *
 * What a crossover does: the toy has two different speakers. The tweeter
 * (left channel) is made for high notes; low notes only make it rattle and
 * waste power. The subwoofer (right channel) is made for low notes; high
 * notes come out of it dull. A crossover splits the sound at one frequency,
 * the crossover point: everything above it goes to the tweeter, everything
 * below it to the subwoofer.
 *
 * How it is built: each side is a filter made of two identical Butterworth
 * "biquads" in a row. A biquad is the standard small digital filter: five
 * numbers (b0, b1, b2, a1, a2) and two memory values. One Butterworth
 * biquad at 1600 Hz is a 2nd-order filter that is -3 dB (half power) at
 * 1600 Hz. Two identical ones in a row make a 4th-order Linkwitz-Riley
 * filter ("LR4"): it cuts twice as steeply (24 dB per octave) and is -6 dB
 * (half the amplitude) at 1600 Hz.
 *
 * Why Linkwitz-Riley: at 1600 Hz the tweeter's LR4 high-pass and the
 * subwoofer's LR4 low-pass are both at half amplitude AND in step (in
 * phase), so 0.5 + 0.5 = 1: together they give the full level. At every
 * other frequency they also add up to the full level; only the timing
 * (phase) of the sum turns a little (an "all-pass"). So the two speakers
 * together sound flat, with no dip and no bump around 1600 Hz. (With one
 * Butterworth biquad per side the two halves would be opposite in phase at
 * 1600 Hz and cancel there.)
 *
 * The subwoofer also gets a 1st-order high-pass at 10 Hz, after its LR4: it
 * removes DC (a constant offset) and rumble below hearing, which would only
 * push the cone and waste power. It is 1st order on purpose: at 10 Hz out of
 * 48 000 Hz a biquad's numbers sit so close to 1 that float rounding spoils
 * them; the 1st-order form stays accurate.
 *
 * Who runs it: TomTask, on every 4 ms half of the DMA buffer (192 stereo
 * frames), whatever the source: playback, tunes, beeps, test patterns and
 * silence. Pure: no RTOS, no HAL, compiles on any host (tests:
 * Tests/OutputChain/test_crossover.c).
 *
 * Main steps:
 *   1. Crossover_Init(48000)            once at start: works out the filter
 *                                       numbers for 1600 Hz and 10 Hz
 *   2. Crossover_ProcessInterleaved()   every half: filters the left and
 *                                       right samples in place; on a silent
 *                                       half whose filters have rung down it
 *                                       does nothing and returns true
 ******************************************************************************
 */
#ifndef CROSSOVER_H
#define CROSSOVER_H

#include <stdbool.h>
#include <stdint.h>

#define CROSSOVER_POINT_HZ        1600.0f      /* the one crossover point (the user's choice): the left LR4 high-pass
                                                * and the right LR4 low-pass both sit here, each -6 dB, so L + R adds
                                                * up flat */
#define CROSSOVER_SUB_HP_HZ         10.0f      /* right: 1st-order high-pass, keeps DC and rumble off the subwoofer */
#define CROSSOVER_BUTTERWORTH_Q   0.70710678f  /* 1/sqrt(2): makes each biquad a Butterworth section (the flattest
                                                * pass band); two in a row = LR4 */
#define CROSSOVER_RUNG_DOWN_LEVEL 0.01f        /* a filter memory value below this (in sample units) has rung down:
                                                * its output rounds to 0, so a silent half can skip the filters */
#define CROSSOVER_SECTIONS_PER_SIDE 2U         /* two Butterworth biquads in a row = one LR4 filter */

/**
 * One biquad, in "transposed direct form II" (two memory values, z1 and z2).
 * For each input sample x it gives
 *     y = b0 x + b1 x[n-1] + b2 x[n-2] - a1 y[n-1] - a2 y[n-2],
 * with the old samples kept inside z1 and z2.
 */
typedef struct
{
    float b0;
    float b1;
    float b2;           /* b: how much of the input (now, 1 and 2 samples ago) */
    float a1;
    float a2;           /* a: how much of the output (1 and 2 samples ago), fed back */
    float z1;
    float z2;           /* memory: what the filter carries to the next sample */
} CrossoverBiquad;

/** The 1st-order high-pass: y = b0 (x - x_prev) + a1 y_prev. */
typedef struct
{
    float b0;
    float a1;
    float x_prev;       /* last input */
    float y_prev;       /* last output */
} CrossoverFirstOrderHighPass;

/** The whole crossover: about 128 bytes, owned by TomTask. */
typedef struct
{
    CrossoverBiquad tweeter[CROSSOVER_SECTIONS_PER_SIDE];   /* left: two Butterworth high-pass biquads = LR4 high-pass */
    CrossoverBiquad sub[CROSSOVER_SECTIONS_PER_SIDE];       /* right: two Butterworth low-pass biquads = LR4 low-pass */
    CrossoverFirstOrderHighPass sub_high_pass;              /* right, after the LR4: the 10 Hz high-pass */
} Crossover;

/**
 * @brief Work out every filter's numbers for this sample rate and clear the
 *        memories.
 * @param crossover      State to set up. NULL is safely ignored.
 * @param sample_rate_hz The DAC rate, 48000 for TomTask.
 */
void Crossover_Init(Crossover *crossover, float sample_rate_hz);

/**
 * @brief Clear every filter memory (the numbers stay).
 * @param crossover State. NULL is safely ignored.
 */
void Crossover_Reset(Crossover *crossover);

/**
 * @brief Filter one block of interleaved stereo frames in place.
 *
 * lr holds [L, R, L, R, ...]: L <- tweeter filter (L), R <- subwoofer
 * filter (R), each rounded to the nearest whole number and clipped to the
 * int16 range (a sharp step can overshoot it).
 *
 * Silence bypass: if every sample is 0 and every filter memory is below
 * CROSSOVER_RUNG_DOWN_LEVEL, the output would be all zeros anyway. Then the
 * filters are skipped, the memories are cleared, lr is left as it is, and
 * the function returns true, so the caller may skip its own per-sample
 * work too (TomTask skips its speaker trim: a trim of 0 is 0).
 *
 * @param crossover State from Crossover_Init.
 * @param lr        2 x frames samples, left first.
 * @param frames    Stereo frames (192 per TomTask half).
 * @return true for a bypassed (silent) block, false when it was filtered
 *         (or for a NULL pointer or 0 frames, which change nothing).
 */
bool Crossover_ProcessInterleaved(Crossover *crossover, int16_t *lr, uint32_t frames);

#endif
